66	{
67	    uint16_t ret = 0xffff;
68	    read_inodemap();
69	    for(int i = 0; i < 512; i++){
70	        uint8_t byte = *(((uint8_t*)inodemap) + i);
71	        if(byte != 0xff){
72	            int bit = 0;
73	            while(byte & (0x01 << bit)){
74	                bit++;
75	            }
76	            ret = 8 * i + bit;
77	            byte = byte | (0x01 << bit);
78	            *(((uint8_t*)inodemap) + i) = byte;
79	            write_inodemap();
80	            read_superblock();
81	            superblock->used_inode_num = superblock->used_inode_num + 1;
