18	int mkfs(int print)
19	{
20	    // Read superblock and check magic
21	    read_superblock();
22	    if(superblock->magic == MAGIC){
23	        current_dir_inode = superblock->root_inode_id;
24	        current_dir_block = superblock->root_block_id;
25	        return 0;
26	    }
27	
28	    // Clear block map
29	    if(print){
30	        prints("[FS] Setting inode-map...\n");
31	    }
32	    memset(blockmap, 0, 512 * 64);
33	    write_blockmap();
34	
35	    // Clear inode map
36	    if(print){
37	        prints("[FS] Setting block-map...\n");
38	    }
39	    memset(inodemap, 0, 512);
40	    write_inodemap();
41	
42	    // Set root dir
43	    if(print){
44	        prints("[FS] Setting root dir...\n");
45	    }
46	    uint16_t inode_id = alloc_inode();
47	    uint32_t block_id = alloc_block();
48	
49	    inode_t* root_inode = read_inode(inode_id);
50	    root_inode->mode = 0;
51	    root_inode->owner = 0;
52	    root_inode->size = 4096;
53	    root_inode->direct_blocks[0] = block_id;
54	    root_inode->link = 2;
55	    write_inode(inode_id);
56	
57	    read_block(block_id);
58	    memset(cached_block_base, 0, 4096);
59	    dir_t* root_dir = cached_block_base;
60	    root_dir->entry[0].type = DIR;
61	    strcpy(root_dir->entry[0].name, ".");
62	    root_dir->entry[0].inode = inode_id;
63	    root_dir->entry[1].type = DIR;
64	    strcpy(root_dir->entry[1].name, "..");
65	    root_dir->entry[1].inode = inode_id;
66	    write_block(block_id);
67	
68	    current_dir_inode = inode_id;
69	    current_dir_block = block_id;
70	
71	    // Write superblock
72	    if(print){
73	        prints("[FS] Setting superblock...\n");
74	        prints("     magic: 0x%lx\n", MAGIC);
75	        prints("     superblock: %d (%d)\n", SUPERBLOCK_ID, 1);
76	        prints("     block-map:  %d (%d)\n", BLOCKMAP_BEGIN_ID, 64);
77	        prints("     inode-map:  %d (%d)\n", INODEMAP_ID, 1);
78	        prints("     inode    :  %d (%d)\n", INODE_BEGIN_ID, 512);
79	        prints("     block    :  %d (%d)\n", BLOCK_BEGIN_ID, 2097152);
80	        prints("     inode entry size: %dB    dir entry size: %dB\n", sizeof(inode_t), sizeof(dir_entry_t));
81	    }
82	    superblock->magic = MAGIC;
83	    superblock->superblock_id = SUPERBLOCK_ID;
84	    superblock->superblock_num = 1;
85	    superblock->blockmap_id = BLOCKMAP_BEGIN_ID;
86	    superblock->blockmap_num = 64;
87	    superblock->inodemap_id = INODEMAP_ID;
88	    superblock->inodemap_num = 1;
89	    superblock->inode_id = INODE_BEGIN_ID;
90	    superblock->inode_num = 512;
91	    superblock->block_id = BLOCK_BEGIN_ID;
92	    superblock->block_num = 2097152;
93	    superblock->root_inode_id = inode_id;
94	    superblock->root_block_id = block_id;
95	    superblock->used_inode_num = 1;
96	    superblock->used_block_num = 1;
97	    write_superblock();
98	
99	    return 1;
100	}
