540	int do_link(char* filename, char* newfile, int mode)
541	{
542	    /* Search Parent Dir */
543	    enable_sum();
544	
545	    int filename_pos = 0;
546	    dir_t* cur_dir;
547	    uint16_t lastdir_inode;
548	    uint32_t lastdir_block;
549	
