565	
566	    char nextdirname[29];
567	    while(1){
568	        // Get name of next dir
569	        int nextdirname_pos = 0;
570	        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
571	            nextdirname[nextdirname_pos++] = filename[filename_pos++];
572	        }
573	        nextdirname[nextdirname_pos] = '\0';
574	
575	        // Last?
576	        if(filename[filename_pos] == '\0'){
577	            break;
578	        }
579	
580	        // Search
581	        int i = 0;
582	        uint16_t nextdir_inode_id;
583	        uint32_t nextdir_block_id;
584	        for(i = 0; i < 128; i++){
585	            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
586	                nextdir_inode_id = cur_dir->entry[i].inode;
587	                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
588	                nextdir_block_id = nextdir_inode->direct_blocks[0];
589	                lastdir_inode = nextdir_inode_id;
590	                lastdir_block = nextdir_block_id;
591	                break;
592	            }
593	        }
594	        if(i == 128){
595	            disable_sum();
596	            return 0;
597	        }
598	
599	        filename_pos++;
600	        read_block(nextdir_block_id);
601	        cur_dir = cached_block_base;
602	    }
603	
604	    disable_sum();
605	    /* Search Parent Dir End */
606	
607	    uint16_t inode_id = 0;
608	    int type = EMPTY;
609	
610	    read_block(lastdir_block);
611	    cur_dir = cached_block_base;
612	    for(int i = 0; i < 128; i++){
613	        if(cur_dir->entry[i].type != EMPTY && !strcmp(cur_dir->entry[i].name, nextdirname)){
614	            inode_id = cur_dir->entry[i].inode;
615	            type = cur_dir->entry[i].type;
616	            break;
617	        }
618	    }
619	    if(type == EMPTY){
620	        return 0;
621	    }
622	
623	    enable_sum();
624	    if(mode == 0){
625	        // hard link: share the same inode
626	        if(type == DIR){
627	            disable_sum();
628	            return 0;
629	        }
630	
631	        inode_t* inode = read_inode(inode_id);
632	        inode->link = inode->link + 1;
633	        write_inode(inode_id);
634	
635	        read_block(current_dir_block);
636	        cur_dir = cached_block_base;
637	        for(int i = 0; i < 128; i++){
638	            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
639	                disable_sum();
640	                return 0;
641	            }
642	        }
643	        for(int i = 0; i < 128; i++){
644	            if(cur_dir->entry[i].type == EMPTY){
645	                cur_dir->entry[i].type = FILE;
646	                strcpy(cur_dir->entry[i].name, newfile);
647	                cur_dir->entry[i].inode = inode_id;
648	                write_block(current_dir_block);
649	                disable_sum();
650	                return 1;
651	            }
652	        }
653	    }
654	    else if(mode == 1){
655	        // soft link: new inode, but shares the target's blocks
656	        read_block(current_dir_block);
657	        cur_dir = cached_block_base;
658	        for(int i = 0; i < 128; i++){
659	            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
660	                disable_sum();
661	                return 0;
662	            }
663	        }
664	        for(int i = 0; i < 128; i++){
665	            if(cur_dir->entry[i].type == EMPTY){
666	                uint16_t new_inode_id = alloc_inode();
667	                cur_dir->entry[i].type = type;
668	                strcpy(cur_dir->entry[i].name, newfile);
669	                cur_dir->entry[i].inode = new_inode_id;
670	                write_block(current_dir_block);
671	                
672	                inode_t* inode = read_inode(inode_id);
673	                uint32_t direct[10];
674	                uint32_t indirect[2];
675	                uint64_t size;
676	                uint32_t link;
677	                for(int j = 0; j < 10; j++){
678	                    direct[j] = inode->direct_blocks[j];
679	                }
680	                indirect[0] = inode->indirect_blocks[0];
681	                indirect[1] = inode->indirect_blocks[1];
682	                size = inode->size;
683	                link = inode->link;
684	
685	                inode = read_inode(new_inode_id);
686	                inode->mode = 1;
687	                inode->owner = current_running[cpu_id]->pid;
688	                inode->size = size;
689	                inode->link = link;
690	                for(int j = 0; j < 10; j++){
691	                    inode->direct_blocks[j] = direct[j];
692	                }
693	                inode->indirect_blocks[0] = indirect[0];
694	                inode->indirect_blocks[1] = indirect[1];
695	                write_inode(new_inode_id);
696	
697	                disable_sum();
698	                return 1;
699	            }
700	        }
701	    }
702	
703	    disable_sum();
704	    return 0;
705	}

