298	int do_fread(int fd, char* buffer, int size)
299	{
300	    if(fd_list[fd].access == O_WRONLY){
301	        return 0;
302	    }
303	
304	    inode_t* inode = read_inode(fd_list[fd].inode);
305	    if(fd_list[fd].rd_pos + size > inode->size){
306	        return 0;
307	    }
308	     
309	    int copied_byte = 0;
310	    while(copied_byte < size){
311	        int block_num = fd_list[fd].rd_pos / 4096;
312	        int block_id;
313	        if(block_num < 10){
314	            block_id = inode->direct_blocks[block_num];
315	        }
316	        else if(block_num >= 10 && block_num < 10 + 1024){
317	            block_id = inode->indirect_blocks[0];
318	            read_block(block_id);
319	            uint32_t* pointer = cached_block_base;
320	            block_id = *(pointer + block_num - 10);
321	        }
322	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
323	            block_id = inode->indirect_blocks[1];
324	            read_block(block_id);
325	            uint32_t* pointer = cached_block_base;
326	            block_id = *(pointer + block_num - 10 - 1024);
327	        }
328	        read_block(block_id);
329	
330	        int offset = fd_list[fd].rd_pos % 4096;
331	        int copy_byte;
332	        if(size - copied_byte <= 4096 - offset){
333	            copy_byte = size - copied_byte;
334	        }
335	        else{
336	            copy_byte = 4096 - offset;
337	        }
338	
339	        enable_sum();
340	        memcpy(buffer + copied_byte, ((uint8_t*)cached_block_base) + offset, copy_byte);
341	        disable_sum();
342	
343	        copied_byte += copy_byte;
344	        fd_list[fd].rd_pos += copy_byte;
345	    }
346	
347	    return size;
348	}
