350	int do_fwrite(int fd, char* buffer, int size)
351	{
352	    if(fd_list[fd].access == O_RDONLY){
353	        return 0;
354	    }
355	
356	    inode_t* inode = read_inode(fd_list[fd].inode);
357	
358	    int cur_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
359	    inode->size = inode->size + size;
360	    int total_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
361	    int needed_block = total_block - cur_block;
362	
363	    if(total_block >= 10 && cur_block < 10){
364	        inode->indirect_blocks[0] = alloc_block();
365	    }
366	    if(total_block >= 10 + 1024 && cur_block < 10 + 1024){
367	        inode->indirect_blocks[1] = alloc_block();
368	    }
369	
370	    for(int i = 0; i < needed_block; i++){
371	        int block_num = cur_block + i;
372	        if(block_num < 10){
373	            inode->direct_blocks[block_num] = alloc_block();
374	        }
375	        else if(block_num >= 10 && block_num < 10 + 1024){
376	            int block_id = inode->indirect_blocks[0];
377	            read_block(block_id);
378	            uint32_t* pointer = cached_block_base;
379	            *(pointer + block_num - 10) = alloc_block();
380	            write_block(block_id);
381	        }
382	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
383	            int block_id = inode->indirect_blocks[1];
384	            read_block(block_id);
385	            uint32_t* pointer = cached_block_base;
386	            *(pointer + block_num - 10 - 1024) = alloc_block();
387	            write_block(block_id);
388	        }
389	    }
390	    
391	    write_inode(fd_list[fd].inode);
392	
393	    int copied_byte = 0;
394	    while(copied_byte < size){
395	        int block_num = fd_list[fd].wr_pos / 4096;
396	        int block_id; 
397	        if(block_num < 10){
398	            block_id = inode->direct_blocks[block_num];
399	        }
400	        else if(block_num >= 10 && block_num < 10 + 1024){
401	            block_id = inode->indirect_blocks[0];
402	            read_block(block_id);
403	            uint32_t *pointer = cached_block_base;
404	            block_id = *(pointer + block_num - 10);
405	        }
406	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
407	            block_id = inode->indirect_blocks[1];
408	            read_block(block_id);
409	            uint32_t *pointer = cached_block_base;
410	            block_id = *(pointer + block_num - 10 - 1024);
411	        }
412	
413	        read_block(block_id);
414	
415	        int offset = fd_list[fd].wr_pos % 4096;
416	        int copy_byte;
417	        if(size - copied_byte <= 4096 - offset){
418	            copy_byte = size - copied_byte;
419	        }
420	        else{
421	            copy_byte = 4096 - offset;
422	        }
423	
424	        enable_sum();
425	        memcpy(((uint8_t*)cached_block_base) + offset, buffer + copied_byte, copy_byte);
426	        write_block(block_id);
427	        disable_sum();
428	
429	        copied_byte += copy_byte;
430	        fd_list[fd].wr_pos += copy_byte;
431	    }
432	
433	    return size;
434	}
