19	// returns pa
20	PTE* alloc_pgdir_page()
21	{
22	    int i;
23	    for(i = 0; i < PGDIR_PAGE_NUM; i++){
24	        if(pgdir_page[i].valid == 0){
25	            break;
26	        }
27	    }
28	    assert(i != PGDIR_PAGE_NUM);
29	    pgdir_page[i].valid = 1;
30	    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
31	    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
32	    return ret;
33	}
