86	// select a user page to write to disk (NRU), returns pa
87	ptr_t selete_page()
88	{
89	    // NRU: prefer a valid, unpinned page whose PTE accessed bit is clear;
90	    // clear the accessed bit of the pages we skip (second chance)
91	    for(int i = 0; i < USER_PAGE_NUM; i++){
92	        if(user_page[i].valid && !user_page[i].pin){
93	            PTE *pte = user_page[i].pgtable;
94	            if(pte == NULL || !get_attribute(*pte, _PAGE_ACCESSED)){
95	                return num2pa(i);
96	            }
97	            clear_attribute(pte, _PAGE_ACCESSED);
98	        }
99	    }
100	    // every candidate was recently used: take the first unpinned one
101	    for(int i = 0; i < USER_PAGE_NUM; i++){
102	        if(user_page[i].valid && !user_page[i].pin){
103	            return num2pa(i);
104	        }
105	    }
106	    // no swappable page at all
107	    assert(0);
108	    return 0;
109	}
110	
111	void write_to_sd(ptr_t pa)
112	{
113	    int num = pa2num(pa);
114	    // find a free swap slot on the disk
115	    int i;
116	    for(i = 0; i < DISK_PAGE_NUM; i++){
117	        if(disk_page[i].valid == 0){
118	            break;
119	        }
120	    }
121	    assert(i != DISK_PAGE_NUM);
122	    disk_page[i].valid = 1;
123	    // write the page to the swap area: 8 sectors (512B) per page
124	    sbi_sd_write((unsigned int)pa, PAGE_SIZE / 512,
125	                 SWAP_BEGIN + i * (PAGE_SIZE / 512));
126	    // mark the owner's PTE as swapped: not present, slot id in the pfn field
127	    PTE *pte = user_page[num].pgtable;
128	    if(pte != NULL){
129	        clear_attribute(pte, _PAGE_PRESENT);
130	        set_pfn(pte, i);
131	        set_attribute(pte, _PAGE_SOFT);
132	    }
133	    user_page[num].valid = 0;
134	    user_page[num].pin = 0;
135	    user_page[num].pgtable = NULL;
136	    local_flush_tlb_all();
137	}
