139	unsigned long free_page_num()
140	{
141	    unsigned long ret = 0;
142	    for(int i = 0; i < USER_PAGE_NUM; i++){
143	        if(user_page[i].valid == 0){
144	            ret++;
145	        }
146	    }
147	    return ret;
148	}
