150	/*
151	 * Virtual Memory Layout
152	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
153	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
154	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
155	 */
156	PTE* init_page_table()
157	{
158	    // allocate a fresh pgdir (pa) and share the kernel mapping with it
159	    PTE *pgdir = alloc_pgdir_page();
160	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
161	    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
162	    // 0xffffffc0_00000000 ~ : VPN2 = 0x101, 2MB-large-page kernel mapping
163	    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];
164	
165	    // allocate and map the user stack: 0xf_0000_f000 ~ 0xf_0001_0000
166	    uintptr_t va = USER_STACK_ADDR - PAGE_SIZE;
167	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
168	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
169	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
170	
171	    PTE *second_level_pgdir = alloc_pgdir_page();
172	    set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
173	    set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
174	
175	    PTE *second_level_kva = (PTE*)pa2kva((uintptr_t)second_level_pgdir);
176	    PTE *last_level_pgdir = alloc_pgdir_page();
177	    set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
178	    set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
179	
180	    PTE *last_level_kva = (PTE*)pa2kva((uintptr_t)last_level_pgdir);
181	    ptr_t user_stack_pa = alloc_user_page(1, last_level_kva + VPN0);
182	    set_pfn(last_level_kva + VPN0, user_stack_pa >> NORMAL_PAGE_SHIFT);
183	    set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
184	    set_attribute(last_level_kva + VPN0, _PAGE_READ);
185	    set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
186	    set_attribute(last_level_kva + VPN0, _PAGE_EXEC);
187	    set_attribute(last_level_kva + VPN0, _PAGE_USER);
188	    set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
189	    set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);
190	
191	    return pgdir;
192	}
193	
194	void free_process_user_page(PTE* pgdir)
195	{
196	    if(pgdir == NULL){
197	        return;
198	    }
199	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
200	    for(int i = 0; i < NUM_PTE_ENTRY; i++){
201	        // the kernel mapping (VPN2 = 0x101) is shared, never free it
202	        if(i == 0x101 || !get_attribute(pgdir_kva[i], _PAGE_PRESENT)){
203	            continue;
204	        }
205	        PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[i]));
206	        for(int j = 0; j < NUM_PTE_ENTRY; j++){
207	            if(!get_attribute(second_level_kva[j], _PAGE_PRESENT)){
208	                continue;
209	            }
210	            PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[j]));
211	            for(int k = 0; k < NUM_PTE_ENTRY; k++){
212	                PTE pte = last_level_kva[k];
213	                if(get_attribute(pte, _PAGE_PRESENT)){
214	                    uintptr_t pa = get_pa(pte);
215	                    // shared-memory pages are owned by shm_page[]
216	                    int s;
217	                    for(s = 0; s < SHM_PAGE_NUM; s++){
218	                        if(shm_page[s].count > 0 && shm_page[s].pa == pa){
219	                            shm_page[s].count--;
220	                            if(shm_page[s].count == 0){
221	                                free_user_page(pa);
222	                                shm_page[s].pa = 0;
223	                            }
224	                            break;
225	                        }
226	                    }
227	                    if(s == SHM_PAGE_NUM){
228	                        free_user_page(pa);
229	                    }
230	                }
231	                else if(get_attribute(pte, _PAGE_SOFT)){
232	                    // the page lives in the swap area: free its disk slot
233	                    disk_page[get_pfn(pte)].valid = 0;
234	                }
235	            }
236	            free_pgdir_page(kva2pa((uintptr_t)last_level_kva));
237	        }
238	        free_pgdir_page(kva2pa((uintptr_t)second_level_kva));
239	    }
240	    free_pgdir_page((uintptr_t)pgdir);
241	}
