243	// pgdir is pa. if va is not mapped, then mapped it
244	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
245	{
246	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
247	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
248	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
249	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
250	
251	    // build the intermediate levels on demand
252	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
253	        PTE *second_level_pgdir = alloc_pgdir_page();
254	        set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
255	        set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
256	    }
257	    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
258	    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
259	        PTE *last_level_pgdir = alloc_pgdir_page();
260	        set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
261	        set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
262	    }
263	    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
264	
265	    // map a freshly allocated user page if the leaf is not present
266	    if(!get_attribute(last_level_kva[VPN0], _PAGE_PRESENT)){
267	        ptr_t pa = alloc_user_page(0, last_level_kva + VPN0);
268	        set_pfn(last_level_kva + VPN0, pa >> NORMAL_PAGE_SHIFT);
269	        set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
270	        set_attribute(last_level_kva + VPN0, _PAGE_READ);
271	        set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
272	        set_attribute(last_level_kva + VPN0, _PAGE_EXEC);
273	        set_attribute(last_level_kva + VPN0, _PAGE_USER);
274	        set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
275	        set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);
276	    }
277	    return get_kva_of(va, pgdir);
278	}
