327	void shm_page_dt(uintptr_t addr)
328	{
329	    disable_preempt();
330	    int i = (addr - SHM_BASE) / PAGE_SIZE;
331	
332	    // unmap the page from the current process's address space
333	    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);
334	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
335	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
336	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
337	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
338	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
339	    if(get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
340	        PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
341	        if(get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
342	            PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
343	            last_level_kva[VPN0] = 0;
344	        }
345	    }
346	
347	    if(i >= 0 && i < SHM_PAGE_NUM && shm_page[i].count > 0){
348	        shm_page[i].count--;
349	        // last user of this shared page: release the physical page
350	        if(shm_page[i].count == 0){
351	            free_user_page(shm_page[i].pa);
352	            shm_page[i].pa = 0;
353	        }
354	    }
355	    local_flush_tlb_all();
356	    enable_preempt();
357	}
