359	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
360	{
361	    uintptr_t va = stval & VA_MASK;
362	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
363	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
364	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
365	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
366	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
367	
368	    // the va has never been mapped: demand paging
369	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
370	        alloc_page_helper(va, pgdir);
371	        local_flush_tlb_all();
372	        return;
373	    }
374	    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
375	    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
376	        alloc_page_helper(va, pgdir);
377	        local_flush_tlb_all();
378	        return;
379	    }
380	    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
381	    PTE *pte = last_level_kva + VPN0;
382	    if(!get_attribute(*pte, _PAGE_PRESENT)){
383	        if(get_attribute(*pte, _PAGE_SOFT)){
384	            // the page was swapped out: swap it back in
385	            int slot = get_pfn(*pte);
386	            ptr_t pa = alloc_user_page(0, pte);
387	            sbi_sd_read((unsigned int)pa, PAGE_SIZE / 512,
388	                        SWAP_BEGIN + slot * (PAGE_SIZE / 512));
389	            disk_page[slot].valid = 0;
390	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
391	            set_attribute(pte, _PAGE_PRESENT);
392	            set_attribute(pte, _PAGE_READ);
393	            set_attribute(pte, _PAGE_WRITE);
394	            set_attribute(pte, _PAGE_EXEC);
395	            set_attribute(pte, _PAGE_USER);
396	            set_attribute(pte, _PAGE_ACCESSED);
397	            set_attribute(pte, _PAGE_DIRTY);
398	            clear_attribute(pte, _PAGE_SOFT);
399	        }
400	        else{
401	            // the va has never been mapped: demand paging
402	            alloc_page_helper(va, pgdir);
403	        }
404	        local_flush_tlb_all();
405	    }
406	}
